import org.junit.Assert;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mockito;
import org.mockito.runners.MockitoJUnitRunner;
import org.stellar.sdk.xdr.PublicKey;
import org.stellar.sdk.xdr.SignerKey;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

@RunWith(MockitoJUnitRunner.class)
public class KeyPairTest {

    @Test
    public void fromSecretSeedCharArrayTest() throws NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        String seed = "SomeRandomSeed";
        byte[] hash = digest.digest(seed.getBytes());

        KeyPair keyPair = KeyPair.fromSecretSeed(hash);
        Assert.assertTrue(keyPair.canSign());
    }

    @Test
    public void fromSecretSeedStringTest() {
        String seed = "SomeRandomSeedStringTest";
        KeyPair keyPair = KeyPair.fromSecretSeed(seed);
        Assert.assertTrue(keyPair.canSign());
    }

    @Test
    public void fromSecretSeedBytesTest() throws NoSuchAlgorithmException {
        byte[] seed = "SomeRandomSeedBytesTest".getBytes();
        KeyPair keyPair = KeyPair.fromSecretSeed(seed);
        Assert.assertTrue(keyPair.canSign());
    }

    @Test
    public void fromAccountIdTest() {
        String accountId = "SomeRandomAccountId";
        KeyPair keyPair = KeyPair.fromAccountId(accountId);
        Assert.assertEquals(accountId, keyPair.getAccountId());
    }

    @Test
    public void fromPublicKeyTest() throws NoSuchAlgorithmException {
        byte[] publicKey = MessageDigest.getInstance("SHA-256").digest();
        KeyPair keyPair = KeyPair.fromPublicKey(publicKey);
        Assert.assertArrayEquals(publicKey, keyPair.getPublicKey());
    }

    @Test
    public void randomTest() {
        KeyPair keyPair = KeyPair.random();
        Assert.assertNotNull(keyPair);
        Assert.assertTrue(keyPair.canSign());
    }

    @Test
    public void getSignatureHintTest() {
        KeyPair keyPair = KeyPair.random();
        Assert.assertNotNull(keyPair.getSignatureHint());
    }

    @Test
    public void getXdrPublicKeyTest() {
        KeyPair keyPair = KeyPair.random();
        Assert.assertNotNull(keyPair.getXdrPublicKey());
    }

    @Test
    public void getXdrSignerKeyTest() {
        KeyPair keyPair = KeyPair.random();
        Assert.assertNotNull(keyPair.getXdrSignerKey());
    }

    @Test
    public void fromXdrPublicKeyTest() {
        PublicKey pk = Mockito.mock(PublicKey.class);
        KeyPair keyPair = KeyPair.fromXdrPublicKey(pk);
        Assert.assertNotNull(keyPair);
    }

    @Test
    public void fromXdrSignerKeyTest() {
        SignerKey sk = Mockito.mock(SignerKey.class);
        KeyPair keyPair = KeyPair.fromXdrSignerKey(sk);
        Assert.assertNotNull(keyPair);
    }

    @Test
    public void signTest() throws NoSuchAlgorithmException {
        byte[] data = MessageDigest.getInstance("SHA-256").digest();
        KeyPair keyPair = KeyPair.random();
        Assert.assertNotNull(keyPair.sign(data));
    }

    @Test
    public void verifyTest() throws NoSuchAlgorithmException {
        byte[] data = MessageDigest.getInstance("SHA-256").digest();
        KeyPair keyPair = KeyPair.random();
        byte[] signature = keyPair.sign(data);

        Assert.assertTrue(keyPair.verify(data, signature));
    }

    @Test
    public void equalsTest() {
        KeyPair keyPair1 = KeyPair.random();
        KeyPair keyPair2 = KeyPair.random();

        Assert.assertFalse(keyPair1.equals(keyPair2));
        Assert.assertTrue(keyPair1.equals(keyPair1));
    }

    @Test
    public void hashCodeTest() {
        KeyPair keyPair = KeyPair.random();

        Assert.assertTrue(keyPair.hashCode() != 0);
    }
}
